  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'سرڪاري رابطي جا پتا، بلنگ رابطا، ۽ ٻاهرين سپورٽ چينلز کي ترتيب ڏيڻ گهرجي PlayHub سائيٽ جي منتظم طرفان هن ترتيب لاءِ. هي صفحو ڄاڻي واڻي غير تصديق ٿيل اي ميل پتي کي ظاهر نٿو ڪري.',
  'On this page' => 'هن صفحي تي',
  'Open Help Center' => 'کليل مدد مرڪز',
  'Open settings' => 'سيٽنگون کوليو',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'سيٽنگون کوليو، سيڪيورٽي ڏانھن وڃو، پوء پاسورڊ استعمال ڪريو يا ٻه عنصر ڊائلاگ. ٻن عنصر جي ترسيل اي ميل يا فون کي سپورٽ ڪري ٿي جڏهن ترتيب ڏنل هجي.',
  'Operational snapshot' => 'آپريشنل تصوير',
  'Optional, but recommended' => 'اختياري، پر سفارش ڪئي وئي',
  'Other' => 'Other',
  'Partnerships, press, and platform operations.' => 'پارٽنرشپ، پريس، ۽ پليٽ فارم آپريشن.',
  'Payment help' => 'ادائگي جي مدد',
  'Platform' => 'پليٽ فارم',
  'Playback' => 'پلئه بیک',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'پلے بیک جي ترقي، بعد ۾ ڏسڻ واري حالت، پسند، تبصرا، سبسڪرپشن، نوٽيفڪيشن، ۽ منتظم تجزيا ڊيٽابيس ۾ محفوظ ٿيل آهن جڏهن تصديق ٿيل پليٽ فارم جي خاصيتن سان ڳنڍيل آهي.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'پلے بیک، تبصرا، پسند، بعد ۾ ڏسو، رڪنيت، نوٽيفڪيشن، پيغام، پبليڪيشن، ۽ ٻولي سيٽنگون مکيه نيويگيشن ۽ اڪائونٽ مينيو ذريعي دستياب آهن.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub هڪ وڊيو پليٽ فارم آهي اپلوڊ ڪرڻ، ڏسڻ، شيڊول ڪرڻ، انتظام ڪرڻ، ۽ هڪ اڪائونٽ مان تخليق ڪندڙ مواد جي چڪاس ڪرڻ.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub هڪ وڊيو پليٽ فارم آهي جيڪو هن ڊيپلائيمينٽ تي هلندڙ آهي، ٺاهيندڙن، ڏسندڙن، برادرين ۽ پليٽ فارم آپريٽرن لاءِ ٺهيل آهي.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub هڪ پليٽ فارم تان خالق چينلز، وڊيو اپ لوڊ، شيڊول پبلشنگ، سبسڪرپشن، تبصرا، پبليڪيشن، بعد ۾ ڏسو، لائيو مواد جا صفحا، ۽ انتظامي اوزار مهيا ڪري ٿو.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub لاگ ان سيشن، API جي تصديق، CSRF/سيڪيورٽي رويي، ٻولي جي چونڊ، موضوع جي چونڊ، اڪائونٽ مينيو اسٽيٽ، ۽ ايپليڪيشن کي ڪم ڪرڻ لاءِ گهربل ٻيون خاصيتون لاءِ ضروري ڪوڪيز ۽ برائوزر اسٽوريج استعمال ڪري ٿو.',
  'playhub_language, theme' => 'playhub_language، موضوع',
  'Popular questions' => 'مشهور سوال',
  'Preference storage' => 'ترجيح اسٽوريج',
  'Privacy Policy' => 'رازداري پاليسي',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'رازداري، ڪوڪيز، اڪائونٽ سيڪيورٽي، سپورٽ پيغام، ۽ چڪاس واري ڊيٽا پاليسين ۽ پس منظر جي رڪارڊ ذريعي هلائي رهيا آهن جيڪي PlayHub سان ڳنڍيل آهن.',
  'Profile, login, security, and settings help.' => 'پروفائل، لاگ ان، سيڪيورٽي، ۽ سيٽنگون مدد.',
