  'Refund' => 'واپسي',
  'Refund and paid feature guidance.' => 'واپسي ۽ ادا ڪيل خصوصيت ھدايت.',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'ادا ڪيل PlayHub خاصيتن لاءِ رقم جي واپسي جو دارومدار ھن ڊيپلائيشن سان منسلڪ حقيقي بلنگ رڪارڊ تي آھي.',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'رقم جي واپسي جي حوالي سان حقيقي بلنگ رڪارڊ ۽ منتظم جي نظرثاني سان ڳنڍيل آهي. جيڪڏهن بلنگ هن ترتيب ڏيڻ لاءِ ترتيب نه ڏني وئي آهي، اتي واپسي لاءِ پليٽ فارم چارج ناهي.',
