  'Retention and access' => 'برقرار رکڻ ۽ رسائي',
  'Review privacy and cookie details for this deployment.' => 'نظرثاني ڪريو رازداري ۽ ڪوڪيز جي تفصيل هن ڊيپلائيمينٽ لاءِ.',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'هن PlayHub کي استعمال ڪرڻ جا ضابطا هڪ ناظر، خالق، يا منتظم جي طور تي.',
