  'Search help articles, topics, or questions...' => 'مدد لاءِ مضمون، عنوان، يا سوال ڳولھيو...',
  'Select a reason' => 'هڪ سبب چونڊيو',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'ھڪڙي يا وڌيڪ وڊيو فائلون چونڊيو، گھربل تفصيل داخل ڪريو، ڪيٽيگري ۽ ٻولي چونڊيو، تھمب نيل شامل ڪريو، نمائش چونڊيو، ۽ شايع ڪريو. سرور جي پروسيسنگ شروع ٿيڻ کان اڳ وڏيون فائلون حصن ۾ اپ لوڊ ڪيون وينديون آهن.',
  'Send a message and it will be saved for admins.' => 'هڪ پيغام موڪليو ۽ اهو منتظمين لاءِ محفوظ ڪيو ويندو.',
  'Send billing details to admin support for review.' => 'نظرثاني لاءِ ايڊمن سپورٽ ڏانهن بلنگ جا تفصيل موڪليو.',
  'Send message' => 'پيغام موڪليو',
  'Send order details through the refund popup.' => 'واپسي پاپ اپ ذريعي آرڊر جي تفصيل موڪليو.',
  'Send us a message' => 'اسان کي هڪ پيغام موڪليو',
  'Sending...' => 'موڪلي رهيو آهي...',
  'Server configured' => 'سرور ترتيب ڏنو',
  'server records' => 'سرور رڪارڊ',
  'Service operation' => 'سروس آپريشن',
  'session, token' => 'سيشن ، نشان',
  'Settings and login' => 'سيٽنگون ۽ لاگ ان',
  'Short summary' => 'مختصر تت',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'سائن ان ڪريو ۽ سيٽنگون استعمال ڪريو اڪائونٽ، پروفائل، پاسورڊ، نوٽيفڪيشن، رازداري، ۽ خالق جي ترجيحن لاءِ. ٺاھيندڙ اپلوڊ ۽ مواد جي مسئلن ۾ شامل ٿيڻ گھرجي وڊيو عنوان، چينل، برائوزر، ۽ اپلوڊ صفحي تي ڏيکاريل ڪا به پروسيسنگ غلطي.',
  'Sign in for account support' => 'اڪائونٽ سپورٽ لاءِ سائن ان ڪريو',
  'Signed in' => 'سائن ان ٿيو',
  'Start uploading' => 'اپلوڊ ڪرڻ شروع ڪريو',
  'Still can’t find an answer?' => 'اڃا تائين جواب نه ملي سگهيو آهي؟',
  'Stored for admins' => 'منتظمين لاءِ محفوظ ٿيل',
  'Stores language, theme, and interface preferences.' => 'اسٽور ٻولي، موضوع، ۽ انٽرفيس ترجيحات.',
  'Studio, playlists, analytics, channels.' => 'اسٽوڊيو، پبليڪيشن، اينالائيٽڪس، چينلز.',
  'Submit a billing or refund message to admin support.' => 'ايڊمن سپورٽ لاءِ بلنگ يا رقم جي واپسي جو پيغام موڪليو.',
  'Submit refund request' => 'واپسي جي درخواست جمع ڪريو',
  'Submit request' => 'درخواست داخل ڪريو',
  'Subscription cancellation' => 'رڪنيت منسوخي',
  'Support dashboard' => 'سپورٽ ڊيش بورڊ',
  'System status' => 'سسٽم جي حالت',
  'Table' => 'ٽيبل',
  'Taxonomies' => 'Taxonomies',
  'Technical issue' => 'ٽيڪنيڪل مسئلو',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'موجوده PlayHub API سان انضمام لاءِ ٽيڪنيڪل نوٽس ۽ ورڪ فلو اپ لوڊ ڪريو.',
  'Tell us more about your question or request...' => 'اسان کي توهان جي سوال يا درخواست بابت وڌيڪ ٻڌايو ...',
  'Terms of Use' => 'استعمال جون شرطون',
  'The configured' => 'ترتيب ڏنل',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ڊولپر جو صفحو لائيو Laravel backend سان ڳنڍيو ويو آھي: روٽ انوینٽري، ڊيٽابيس ڳڻپ، اپلوڊ جون حدون، ۽ پليٽ فارم ميٽا ڊيٽا /api/developers تان لوڊ ڪيا ويا آھن.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'فرنٽ اينڊ اسٽوري ترجيحات جهڙوڪ چونڊيل ٻولي، موضوع، پلے بیک قطار، ڏسڻ جي پيش رفت، ۽ انٽرفيس جي حالت، تنهن ڪري تجربو ساڳيو رهي ٿو صفحي جي نيويگيشن ۽ ٻيهر لوڊ ڪرڻ تي.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'پروسيسنگ جاب رينڊيشنز کي انڪوڊ ڪري ٿو، ضرورت جي صورت ۾ ٿامب نيل ٺاهي ٿو، ڪيپشن محفوظ ڪري ٿو، ۽ وڊيوز تيار ڪري ٿو جڏهن پروسيسنگ مڪمل ٿئي ٿي. مستقبل جي شيڊول ٿيل وڊيوز نجي رهنديون جيستائين شيڊيولر انهن کي جاري نه ڪري.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'اپلوڊ سسٽم ڊيٽابيس جي مدد سان آهي، API مان ڪيٽيگريز ۽ ٻولين کي سپورٽ ڪري ٿو، اپلوڊ ڪيل وڊيوز تي عمل ڪري ٿو، ٿامب نيل ۽ ڪيپشن کي اسٽور ڪري ٿو، ۽ شيڊول ٿيل مواد کي ان جي رليز جي وقت تائين پرائيويٽ رکي ٿو.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'هي صفحو وضاحت ڪري ٿو ته ڪيئن PlayHub سيشن، سيڪيورٽي، ترجيحات، پلے بیک، ۽ تصديق ٿيل خاصيتن لاء ڪوڪيز ۽ برائوزر اسٽوريج استعمال ڪري ٿو.',
  'Ticket source' => 'ٽڪيٽ جو ذريعو',
  'Top content categories' => 'مٿين مواد جا زمرا',
  'Topic' => 'موضوع',
  'Transaction / invoice' => 'ٽرانزيڪشن / انوائس',
  'Transaction / invoice ID' => 'ٽرانزيڪشن / انوائس ID',
  'Unable to send message.' => 'پيغام موڪلڻ کان قاصر.',
  'Unable to submit refund request.' => 'واپسي جي درخواست جمع ڪرڻ ۾ ناڪام.',
  'Understanding admin support tickets' => 'سمجھڻ منتظم سپورٽ ٽڪيٽن',
  'Upload and processing help' => 'اپلوڊ ۽ پروسيسنگ مدد',
  'Upload chunks' => 'ٽڪر اپ لوڊ ڪريو',
  'Upload issues' => 'اپلوڊ مسئلا',
  'Upload languages' => 'ٻوليون اپ لوڊ ڪريو',
  'Upload limit' => 'اپ لوڊ جي حد',
  'Upload options' => 'اپلوڊ جا اختيار',
  'Upload or processing' => 'اپ لوڊ يا پروسيسنگ',
  'Upload page' => 'اپ لوڊ صفحو',
  'Upload pipeline' => 'اپ لوڊ پائپ لائن',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'لائيو PlayHub ڊيٽا سان اپ لوڊ ڪريو، ڏسو، رڪنيت حاصل ڪريو، معتدل، ۽ تعمير ڪريو.',
  'Uploaded videos' => 'اپ لوڊ ڪيل وڊيوز',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'اپلوڊ ٿيل وڊيوز انڪوڊ ٿيل آهن راند جي قابل رينڊشنز ۾. پروسيسنگ وقت فائل جي سائيز، مدت، سرور لوڊ، ۽ قطار جي حيثيت تي منحصر آهي. اپلوڊ صفحو ۽ خالق اسٽوڊيو ويڊيو رڪارڊ مان حقيقي پروسيسنگ اسٽيٽس ڏيکاري ٿو.',
  'Uploads, scheduling, and processing are available.' => 'اپلوڊ، شيڊول، ۽ پروسيسنگ موجود آهن.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'استعمال ڪريو /api/ويڊيوز، چينل جي آخري پوائنٽ، ۽ تصديق ٿيل رستا ٺاھيندڙ ورڪ فلوز لاءِ.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'وڊيوز ۽ تبصرن لاءِ بلٽ ان رپورٽ ڪارناما استعمال ڪريو ته جيئن منتظمين کي صحيح مواد جو حوالو ملي. ايڊمن ڊيش بورڊ صفحا استعمال ڪندا آھن لائيو ڊيٽابيس ڊيٽا استعمال ڪندڙن لاءِ، مواد، رپورٽون، منيٽائيزيشن، اينالائيٽڪس، سپورٽ، ڪردار، ۽ سسٽم سيٽنگون.',
  'Use Contact Us' => 'استعمال ڪريو اسان سان رابطو ڪريو',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'عام API درخواستن لاءِ JSON استعمال ڪريو ۽ فائل اپ لوڊ ڪرڻ لاءِ FormData. تصديق کي نظرانداز نه ڪريو: زمرا ۽ ٻوليون ڊيٽابيس IDs آهن، نمائش عوامي، غير فهرست ٿيل، يا خانگي تائين محدود آهي، ۽ ڪيپشن SRT، VTT، يا TXT فائلن کي قبول ڪن ٿا.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'پنهنجي پروفائل، سيڪيورٽي، پاسورڊ، ٻه عنصر پهچائڻ، ڊوائيسز، ترجيحات، ۽ نوٽيفڪيشن اختيارن کي اپڊيٽ ڪرڻ لاء سيٽنگون استعمال ڪريو. جيڪڏهن توهان پنهنجي اڪائونٽ تائين رسائي نٿا ڪري سگهو، لاگ ان فلو استعمال ڪريو ۽ سائيٽ ايڊمنسٽريٽر کي اڪائونٽ اي ميل مهيا ڪريو.',
  'Use the contact form' => 'رابطو فارم استعمال ڪريو',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'وڊيوز، تبصرن، ۽ ڪميونٽي پوسٽن تي رپورٽ ڪارناما استعمال ڪريو ته جيئن منتظمين کي صحيح مواد جو حوالو ملي.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'وڊيوز، تبصرن، ۽ ڪميونٽي پوسٽن تي رپورٽ ڪارناما استعمال ڪريو جڏھن مواد پليٽ فارم جي ضابطن جي ڀڃڪڙي ڪري سگھي ٿي. اهي رپورٽون حقيقي مواد جي رڪارڊ سان ڳنڍيل آهن ۽ عام پيغام کان بهتر آهن ڇو ته منتظمين صحيح شيون جو جائزو وٺي سگهن ٿا.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'اڪائونٽ مدد، مواد جي رپورٽن، ٽيڪنيڪل مسئلن، ۽ منتظم جي درخواستن لاء صحيح PlayHub چينل استعمال ڪريو.',
  'Video categories' => 'وڊيو زمرا',
  'Video for everyone. Built for creators and viewers.' => 'وڊيو سڀني لاء. حقيقي پليٽ فارم ڊيٽا مان ٺهيل.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'وڊيو اپلوڊ، شيڊيولنگ، ٿامب نيل، ۽ پروسيسنگ جا مسئلا.',
  'Videos, thumbnails, captions, processing.' => 'وڊيوز، ٿمبنيلز، ڪيپشن، پروسيسنگ.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ناظرین ڪيٽيگريز کي براؤز ڪري سگهن ٿا، وڊيوز ڳولي سگهن ٿا، مواد ڏسي سگهن ٿا، چينلن جي رڪنيت حاصل ڪري سگهن ٿا، بعد ۾ ڏسڻ لاءِ وڊيوز محفوظ ڪري سگهن ٿا، تبصرو ڪري سگهن ٿا، نوٽيفڪيشن وصول ڪري سگهن ٿا، ۽ ٻولي ۽ رسائي جي ترجيحن کي منظم ڪري سگهن ٿا.',
  'Viewing and community help' => 'ڏسڻ ۽ ڪميونٽي جي مدد',
  'Waiting for backend endpoint inventory.' => 'پس منظر جي آخري پوائنٽ جي فهرست جي انتظار ۾.',
  'We’re here to help.' => 'اسان هتي آهيون مدد ڪرڻ لاءِ.',
  'What is PlayHub?' => 'PlayHub ڇا آهي؟',
  'What PlayHub does' => 'PlayHub ڇا ڪندو آهي',
  'Where do contact messages go?' => 'رابطي جا پيغام ڪيڏانهن وڃن ٿا؟',
  'Why is my video still processing?' => 'منهنجي وڊيو اڃا پروسيسنگ ڇو ٿي رهي آهي؟',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'ها. اپلوڊ صفحي تي اصلي شيڊول جي تاريخ ۽ وقت جي فيلڊ استعمال ڪريو. پس منظر شيڊول_at کي اسٽور ڪري ٿو، وڊيو کي پروسيس ڪري ٿو، ان کي پرائيويٽ رکي ٿو جڏهن تاريخ مستقبل ۾ آهي، ۽ ان کي جاري ڪري ٿو جڏهن Laravel شيڊيولر مقرر وقت کان پوءِ هلندو آهي.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'ها. اپلوڊ تي اصلي شيڊول فيلڊ استعمال ڪريو. پس منظر شيڊول_at کي اسٽور ڪري ٿو ۽ پروسيسنگ کان پوءِ وڊيو جاري ڪري ٿو جڏهن شيڊول جو وقت پهچي وڃي ٿو.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'توهان مهمان طور برائوزنگ ڪري رهيا آهيو. اڪائونٽ-مخصوص اوزار تائين رسائي حاصل ڪرڻ لاءِ سائن ان ڪريو.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'توهان ذميوار آهيو توهان جي اڪائونٽ جي سند، پروفائل سرگرمي، اپلوڊ ڪيل مواد، تبصرا، پيغام، ۽ توهان جي اڪائونٽ مان ڪيل ڪنهن به خالق يا منتظم جي عملن جا. مضبوط پاسورڊ استعمال ڪريو ۽ ٻه عنصر پهچائڻ جا طريقا موجوده رکو.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'توھان پنھنجي برائوزر سيٽنگن ۾ برائوزر ڪوڪيز ۽ مقامي اسٽوريج کي صاف ڪري سگھو ٿا. ضروري اسٽوريج کي صاف ڪرڻ شايد توهان کي سائن آئوٽ ڪري، ٻولي/موضوع جي ترجيحن کي ري سيٽ ڪري، مقامي پلے بیک اسٽيٽ کي هٽائي، ۽ توهان کي ٻيهر لاگ ان ٿيڻ جي ضرورت آهي.',
  'You receive a response by email.' => 'توهان اي ميل ذريعي جواب حاصل ڪندا.',
  'You’re in control' => 'توهان ڪنٽرول ۾ آهيو',
  'Your choices' => 'توهان جون چونڊون',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'توهان جو پيغام سڌو سنئون ويب سائيٽ جي پس منظر ۾ محفوظ ڪيو ويو آهي ۽ مدد جي تحت منتظم ڊيش بورڊ ۾ ظاهر ٿئي ٿو.',
  'Your support' => 'توهان جي حمايت',
