  'Upload your first video and give viewers a clear reason to subscribe.' => 'پنھنجو پھريون وڊيو اپلوڊ ڪريو ۽ ڏسندڙن کي رڪنيت حاصل ڪرڻ لاءِ واضح دليل ڏيو.',
  'Use Shorts for discovery' => 'دريافت ڪرڻ لاءِ Shorts استعمال ڪريو',
  'Keep testing quick hooks and link viewers to longer videos.' => 'تڪڙا ٿلها ٽيسٽ ڪندا رهو ۽ ڏسندڙن کي ڊگھي وڊيوز سان ڳنڍيو.',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'مختصر عمودي وڊيوز ٺاھيو انھن ناظرين تائين پھچڻ لاءِ جن اڃا تائين توھان جو چينل نه لڌو آھي.',
  'Create short' => 'مختصر ٺاهيو',
  'Turn comments into loyalty' => 'تبصرن کي وفاداري ۾ تبديل ڪريو',
  'Reply to recent comments and turn viewers into returning fans.' => 'تازن تبصرن جو جواب ڏيو ۽ ڏسندڙن کي موٽندڙ مداحن ۾ تبديل ڪريو.',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'توهان جي ايندڙ اپلوڊ ۾ هڪ سوال پڇو ۽ جلدي جواب ڏيو جڏهن رايا اچن.',
  'View comments' => 'تبصرا ڏسو',
