  'Upload planner' => 'اپلوڊ پلانر',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'عنوانن، ٽيگ، ڏيک، ۽ ٿامب نيل قدمن سان نئون اپلوڊ شروع ڪريو.',
  'Shorts studio' => 'شارٽس اسٽوڊيو',
  'Create short videos for faster discovery and mobile viewers.' => 'تيز دريافت ۽ موبائل ڏسندڙن لاءِ مختصر وڊيوز ٺاهيو.',
