  'Channel profile' => 'چينل پروفائل',
  'Update your bio, channel details, and public creator presence.' => 'تازه ڪاري ڪريو پنھنجي بائيو، چينل جي تفصيل، ۽ عوامي خالق جي موجودگي.',
  'Audience building' => 'سامعين جي عمارت',
  'Study subscribers, comments, and what viewers respond to most.' => 'مطالعي جا رڪن، تبصرا، ۽ جيڪي ناظرین سڀ کان وڌيڪ جواب ڏين ٿا.',
